(() => {
  const el=id=>document.getElementById(id);
  let contexts, scenario='design', turns=[], busy=false, ready=false, generation=0, controller;
  const sourceText={design:'Until 28 November · expected payday',engine:'Another profile · 1–30 October'};
  function setBusy(value){busy=value;el('chat-send').disabled=value||!ready;el('chat-input').disabled=value||!ready;document.querySelectorAll('[data-prompt]').forEach(b=>b.disabled=value||!ready);el('chat-log').setAttribute('aria-busy',String(value));}
  function addMessage(role,text){const article=document.createElement('article');article.className=`message message-${role}`;const label=document.createElement('span');label.className='message-label';label.textContent=role==='user'?'You':'Your coach';const p=document.createElement('p');p.textContent=text;article.append(label,p);el('chat-log').append(article);el('chat-log').scrollTop=el('chat-log').scrollHeight;return article;}
  function clear(){generation++;controller?.abort();turns=[];el('chat-log').replaceChildren();el('chat-input').value='';el('chat-error').hidden=true;el('chat-retry').hidden=true;setBusy(false);el('chat-status').textContent=ready?'Ready to talk':'Chat is not connected yet. Your plan is still available.';}
  function showScenario(next){clear();scenario=next;const c=contexts?.[scenario];if(!c)return;document.querySelectorAll('[data-scenario]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scenario===scenario)));el('coach-source').textContent=sourceText[scenario];el('coach-summary-title').textContent=c.title;el('coach-explanation').textContent=c.explanation;el('coach-facts').replaceChildren();for(const f of c.facts){const d=document.createElement('div');const label=document.createElement('span');label.textContent=f.label;const value=document.createElement('strong');value.textContent=f.value;d.append(label,value);el('coach-facts').append(d);}el('coach-details').replaceChildren();for(const text of [c.source,...c.details]){const p=document.createElement('p');p.textContent=text;el('coach-details').append(p);}el('chat-input').placeholder=scenario==='engine'?'Ask about this October plan…':'What’s on your mind?';}
  async function submit(message){if(busy||!ready||!message.trim())return;const requestGeneration=generation;const user=addMessage('user',message);const pending=addMessage('assistant','Thinking through your question…');pending.classList.add('message-pending');el('chat-error').hidden=true;el('chat-retry').hidden=true;el('chat-status').textContent='Your coach is replying…';setBusy(true);controller=new AbortController();const timeout=setTimeout(()=>controller?.abort(),30000);try{const response=await fetch('/api/coach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scenario,message,history:turns.slice(-8)}),signal:controller.signal});const data=await response.json();if(requestGeneration!==generation)return;if(!response.ok||typeof data.reply!=='string')throw new Error(data.error||'The coach couldn’t reply. Try again.');pending.classList.remove('message-pending');pending.querySelector('p').textContent=data.reply;el('chat-log').scrollTop=el('chat-log').scrollHeight;turns.push({role:'user',text:message},{role:'assistant',text:data.reply.slice(0,2400)});el('chat-input').value='';el('chat-status').textContent='Your coach has replied';}catch(error){if(requestGeneration!==generation)return;pending.remove();user.remove();el('chat-error').textContent=error.name==='AbortError'?'The reply took too long. Please try again.':error.message;el('chat-error').hidden=false;el('chat-retry').hidden=false;el('chat-status').textContent='Message not sent successfully';}finally{clearTimeout(timeout);if(requestGeneration===generation){setBusy(false);el('chat-input').focus({preventScroll:true});}}}
  el('chat-form').addEventListener('submit',event=>{event.preventDefault();submit(el('chat-input').value.trim());});
  el('chat-input').addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();el('chat-form').requestSubmit();}});
  el('chat-retry').addEventListener('click',()=>submit(el('chat-input').value.trim()));
  el('clear-chat').addEventListener('click',clear);
  document.querySelectorAll('[data-prompt]').forEach(button=>button.addEventListener('click',()=>{el('chat-input').value=button.dataset.prompt;submit(button.dataset.prompt);}));
  document.querySelectorAll('[data-scenario]').forEach(button=>button.addEventListener('click',()=>showScenario(button.dataset.scenario)));
  async function load(){setBusy(true);try{const response=await fetch('/api/coach');if(!response.ok)throw new Error();const data=await response.json();if(!data.contexts?.design||!data.contexts?.engine)throw new Error();contexts=data.contexts;ready=data.ready;showScenario(scenario);}catch{ready=false;el('coach-source').textContent='Your plan couldn’t load.';el('chat-status').textContent='Please reload to reconnect.';setBusy(false);}}
  load();
})();
